const player = {
  points: 120,
  get level() {
    return Math.floor(this.points / 100);
  },
  set bonus(amount) {
    this.points += amount;
  },
};

player.bonus = 90;

try {
  player.level = 9;
} catch (error) {
  console.log(error.name);
}

console.log(player.bonus);
console.log(player.level);
